  for(let k=0;k<36;k++){const c=STRATOS_TRI[k];
    P[o]=STRATOS_CX[c]?xb:xa;P[o+1]=STRATOS_CY[c]?yb:ya;P[o+2]=STRATOS_CZ[c]?zb:za;C[o]=r;C[o+1]=g;C[o+2]=b;o+=3;}
