  b.innerHTML='<div class="ebCarte"><small class="ebTit'+(cap9?' cap':'')+'">'+(cap9?'+ '+sansAcc(TR(cap9)):sansAcc(TR(rec?'NOUVEAU SOMMET':'NOUVEAU MOTEUR')))+'</small>'
    +'<b data-t="'+String(nm).replace(/[<>&"]/g,'')+'">'+nm+'</b>'
