    for(let i=0;i<14;i++){const s9=4+Math.random()*8;spawnP(boomEmbO,IMP.q.x,IMP.q.y,IMP.q.z,N.x*s9+(Math.random()-.5)*6,N.y*s9+2+Math.random()*5,N.z*s9+(Math.random()-.5)*6,.5+Math.random()*.6);}
