/* (2026-10-14, session SON) LE MOTEUR RESPIRE. À vitesse tenue la hauteur était figée au hertz près (audit n°3 §8 : `wob` ne vit que sous
   29 % de régime, `drift9` ne touche que le filtre) — un bourdon fixe sur les longues lignes des paliers 20-30, sans rapports. Deux sinus
   lents sans rapport simple (0,23 et 0,37 Hz : jamais un vibrato, jamais Math.random par image) bougent la hauteur de ±0,7 % au plus
   (12 cents, bien sous le demi-ton). Il ne s'allume qu'APRÈS le tremblement du ralenti (`wob`, éteint à 29 % de régime) : plein à 49 %. */
function engSouffle(t,rpm){return .007*(.62*Math.sin(t*1.45)+.38*Math.sin(t*2.31+1.7))*Math.min(1,Math.max(0,(rpm-.29)/.2));}
window.dbgGenou=function(v){if(v!=null)ENG_DOUX=!!v;return {genou:ENG_DOUX,hz:ENG_GENOU,puissance:ENG_GENOU_P};};
/* (2026-10-05) LES RÉGLAGES D'UNE IMAGE APPLIQUÉS AUX NŒUDS DU MOTEUR — sortis de la boucle de course pour que le BURN-OUT du garage
   (voir LE BURN-OUT) fasse chanter le MÊME moteur, au même timbre, sans recopier une ligne. */
function engApplique(P9){
  const T=AC.currentTime;
  stt(osc.frequency,P9.fF,T,.035);
  stt(osc2.frequency,P9.fF,T,.04);
  stt(osc2.detune,P9.detune,T,.07);   // l'ÉPAISSEUR : deux voix qui s'écartent battent
  stt(engSub.frequency,P9.subF,T,.05);
  stt(engNzF.frequency,P9.nzF,T,.06);
  stt(engNzG.gain,P9.nzG,T,.07);
  if(P9.whineOn)stt(engWhine.frequency,P9.whineF,T,.04);
  stt(engWhineG.gain,P9.whineG,T,.06);
  stt(engPre.gain,P9.drv,T,.06);
  stt(engPost.gain,P9.post,T,.06);
  stt(engEq.gain,P9.eq,T,.09);
  stt(engMix.gain,P9.mix,T,.05);
  stt(engSubG.gain,P9.subG,T,.08);
  stt(engTickO.frequency,P9.tickF,T,.03);
  stt(engTickG.gain,P9.tickG,T,.07);
  stt(pinkG.gain,P9.pinkG,T,.10);
  stt(transO.frequency,P9.transF,T,.08);
  stt(diffO.frequency,P9.diffF,T,.08);
  stt(transG.gain,P9.transG,T,.10);
  stt(diffG.gain,P9.diffG,T,.10);
  stt(ovrF.frequency,P9.ovrF,T,.06);
  stt(ovrG.gain,P9.ovrG,T,.05);
  stt(filt.frequency,P9.lp,T,.06);
  stt(gainN.gain,P9.ev,T,.08);
  stt(engLfo.frequency,P9.lfoF,T,.1);
  stt(engLfoG.gain,P9.lfoG,T,.1);
}
function engCurve(k){ // courbe de saturation tanh — le grain qui devient hargne quand on pousse dedans
  const n=256,c=new Float32Array(n);
  for(let i=0;i<n;i++){const x=i/(n-1)*2-1;c[i]=Math.tanh(x*k)/Math.tanh(k);}
  return c;
}
// ⚠ RENOMMÉ `engSetTier` (2026-08-05) : il ne charge plus une voix de CAISSE mais la voix du
// PALIER MOTEUR. Le nom `engSetCar` mentait depuis qu'on a tranché « le bruit du moteur, c'est
// le moteur » — et un nom qui ment finit toujours par faire recâbler quelqu'un à la mauvaise
// source. `lv` est maintenant un index de `ENG_SND`, c'est-à-dire `engTier` lui-même.
function engSetTier(lv){ // changement de palier → nouveau timbre (onde harmonique + grain + sub), à chaud
  if(!AC||!osc)return;
  const e=ENG_SND[lv]||ENG_SND[0];engLvl=lv;engGear=1;engShiftT=0;
  const w=engWave9(AC,e);                       // l'onde du palier — fabriquée par le bloc balisé
  osc.setPeriodicWave(w);osc2.setPeriodicWave(w);osc2.detune.value=7;
  // LA GORGE du palier : fixe, elle ne suit pas le régime (c'est tout l'intérêt)
  if(engFmt){const F=e.fmt||[110,1.2,3];
    engFmt.frequency.value=F[0];engFmt.Q.value=F[1];engFmt.gain.value=F[2];}
  engSubG.gain.value=e.sub*.5;
  engShaper.curve=engCurve(e.dr);
  try{if(MV.on)MV.tier(lv);}catch(_){} /* (2026-10-22) le moteur vivant change de fiche avec le palier */
}
function crackle(amt){ // crépitements d'échappement au lâcher : pop-pop-pop dense puis qui s'égrène
  if(!sfxOk())return;
  try{
    const t0=AC.currentTime;let tt=0;
    const n=2+Math.floor(Math.random()*4+amt*3);
    for(let i=0;i<n;i++){
      const src=AC.createBufferSource();src.buffer=noiseBuf(.06);
      const f=AC.createBiquadFilter();f.type='bandpass';f.Q.value=1.6;f.frequency.value=280+Math.random()*620;
      const g=AC.createGain();const big=Math.random()<.2;
      g.gain.setValueAtTime(big?.3:.08+Math.random()*.13,t0+tt);
      g.gain.exponentialRampToValueAtTime(.001,t0+tt+(big?.06:.03));
      src.connect(f);f.connect(g);g.connect(MASTER);src.start(t0+tt);src.stop(t0+tt+.09);
      tt+=.03+Math.random()*.08*(1+i*.3);
    }
  }catch(e){}
}
// (2026-09-25) LA GARDE DES SONS PONCTUELS : contexte absent, SON coupé, pause ou iOS « interrupted » → on ne fabrique RIEN.
// Sans elle, chaque pièce, pop et carillon était créé sur une horloge figée, gardé en mémoire, puis joué d'un bloc au rallumage.
function sfxOk(){return !!AC&&SND.sfx&&AC.state==='running';}
/* ===== LE MOTEUR VIVANT EN JEU (2026-10-22, session SON ; Sacha : « c'est bon, intègre le moteur vivant au jeu derrière un drapeau (?moteurvivant=1), l'ancien reste par défaut ») =====
   Le DSP est dans assets/audio/moteur-vivant/ (moteur-vivant.js + worklet-moteur.js, un AudioWorklet) ; l'atelier d'écoute et ses bancs sont dans
   atelier-son/moteur-vivant/ (hors ligne, jamais publié). ICI, seulement le BRANCHEMENT : ce que la boucle sait (régime de la boîte virtuelle, pédale, charge,
   nitro, ducking, rapport en cours) devient les commandes du moteur vivant, et ce qu'il fait entendre prend la place de la chaîne d'oscillateurs.
   · SANS le drapeau : rien n'est chargé, rien ne change, au bit près (MV.on = false : chaque appel ci-dessous sort tout de suite).
   · AVEC : les paliers à PISTONS (0 à 18) chantent avec le moteur vivant ; les turbines et réacteurs (19 à 29) gardent l'ancienne voix (un moteur à
     pistons n'a rien à dire d'un cœur à fusion). Le moteur vivant RÉUSSIT À ENTRER → `MV.use` ; sinon (pas d'AudioWorklet, fichier introuvable) rien ne change.
   · LES TROIS FICHES : V8 croisé (la plupart), 6 en ligne TURBO (paliers 5, 6, 8, 17 : ceux qui avaient un `whine`), PLAT-PLAN aigu (les V10, V12, W12,
     V16, H16, rotatif). LE VIEILLISSEMENT SERT DE LADDER : les quatre premiers paliers sonnent USÉS (santé .40 · .55 · .68 · .78 : ratés, tic des culbuteurs,
     coup de bielle) et le moteur « se répare » en montant — l'épave du début tousse, le palier 5 est rodé.
   · CE QUE LE JEU DONNE : le régime de la boîte virtuelle (engRpm 0..1 → ralenti..rupteur), la pédale (monte en 70 ms, retombe d'un coup : c'est ce qui
     déclenche le crépitement), la charge (`charge9`), le nitro (+4 % de régime), le ducking `dk`. Le passage de rapport COUPE les gaz (`engShiftT`) : le moteur
     vivant y met son « blap » ; les crépitements de l'ancienne chaîne (`crackle`) se taisent pendant ce temps (sinon deux pétarades à chaque rapport).
   · LA MORT (explosion) coupe net ; la SECONDE CHANCE (le moteur perd un palier) lui donne un choc ; le RETOUR en course rallume.
   · LA MUSIQUE : `MUS_WA.bus.moteur(présence)` — la musique s'efface de 3,5 dB à 850 Hz (et 2,5 à 1 800 Hz) pendant que le moteur parle (mesuré : c'est là que
     moteur = musique − 7 dB la couvre). Lissé 250 ms, rendu au silence quand le moteur se tait.
   · RÉGLAGES (adresse) : `?mvg=1.3` le niveau (1 = calé sur musique − 7 dB) · `?mvcreux=0` sans le creux dynamique · `?mvsante=.5` impose la santé (banc).
   · `dbgMV()` : l'état. Pas de coût hors drapeau ; avec, ~2-3 % d'un cœur (mesuré hors ligne : 15× le temps réel). */
const MV={on:/[?&]moteurvivant=1\b/.test(location.search),ok:false,use:false,node:null,hp:null,g:null,nom:'',lv:0,sante:1,etat:'off',rpm:0,niv:0,pres:0,thrS:0,vu:0,msgT:0,carveT:0,mort:false,
  niveau:+((/[?&]mvg=([\d.]+)/.exec(location.search)||[])[1])||1,creux:!/[?&]mvcreux=0\b/.test(location.search),
  santeImp:(/[?&]mvsante=([\d.]+)/.exec(location.search)||[])[1],
  cfg:{v8:{idle:760,redline:6500},flat:{idle:900,redline:8800},l6:{idle:740,redline:7000}}};
MV.nomDe=function(lv){return lv>18?null:(lv===5||lv===6||lv===8||lv===17)?'l6':(lv>=12)?'flat':'v8';};
MV.envoi=function(o){if(MV.node)try{MV.node.port.postMessage(o);}catch(e){}};
/* le palier a changé (engSetTier) : la fiche, et la santé (l'épave du début) */
MV.tier=function(lv){
  if(!MV.on)return;MV.lv=lv;const nom=MV.nomDe(lv);MV.sante=MV.santeImp!=null?+MV.santeImp:[.40,.55,.68,.78][lv]||1;
  MV.use=!!nom&&MV.ok;if(!nom)return;
  if(nom!==MV.nom){MV.nom=nom;MV.envoi({moteur:nom});}
};
MV.build=function(){
  if(!MV.on||MV.node||!AC||!AC.audioWorklet)return;
  const B='assets/audio/moteur-vivant/',v='?v=2';
  AC.audioWorklet.addModule(B+'moteur-vivant.js'+v).then(function(){return AC.audioWorklet.addModule(B+'worklet-moteur.js'+v);}).then(function(){
    const n=new AudioWorkletNode(AC,'moteur-vivant',{outputChannelCount:[2],processorOptions:{moteur:MV.nom||'v8'}});
    const hp=AC.createBiquadFilter();hp.type='highpass';hp.frequency.value=TEL_NATIF?150:55;hp.Q.value=.7; /* le coupe-bas du moteur : le grave est à la musique (téléphone : le haut-parleur ne le rend pas) */
    const g=AC.createGain();g.gain.value=0;n.connect(hp);hp.connect(g);g.connect(MASTER);
    n.port.onmessage=function(e){const d=e.data;MV.rpm=d.rpm;MV.etat=d.etat;MV.niv=d.niv;};
    MV.node=n;MV.hp=hp;MV.g=g;MV.ok=true;MV.envoi({ev:'allume'});MV.tier(MV.lv);
    /* le garde-fou : plus aucune commande depuis 0,7 s (menu, pause, onglet caché) → le moteur se tait et la musique reprend sa place */
    setInterval(function(){if(MV.g&&performance.now()-MV.vu>700){MV.g.gain.setTargetAtTime(0,AC.currentTime,.08);MV.envoi({c:{thr:0,load:0}});MV.creuse(0);}},250);
  }).catch(function(e){MV.on=false;MV.use=false;try{console.warn('moteur vivant : repli sur l\'ancien moteur',e);}catch(_){}});
};
/* la musique recule là où le moteur parle (musique-bus.js, `moteur`) */
MV.creuse=function(p){
  MV.pres+=(p-MV.pres)*.25;if(!MV.creux)return;const t=performance.now();if(t-MV.carveT<100)return;MV.carveT=t;
  try{if(musWaTient()&&MUS_WA.bus&&MUS_WA.bus.moteur)MUS_WA.bus.moteur(MV.pres);}catch(e){}
};
/* UNE IMAGE de conduite : appelée par la boucle (au sol : engRpm de la boîte ; en l'air : la roue libre). `fall` : le moteur emballé en vol, plus discret. */
MV.drive=function(dt,rpmN,thr,charge,nA,dk,fall){
  if(!MV.on||!MV.ok||!MV.use||!AC)return;
  const C=MV.cfg[MV.nom];if(!C)return;
  if(MV.mort){MV.mort=false;MV.envoi({ev:'allume'});}
  MV.vu=performance.now();
  /* l'ancienne chaîne se tait : seule sa « mix » (oscillateurs, sub, souffle, tic) ; la boîte, le pont et le frein moteur restent */
  try{stt(engMix.gain,0,AC.currentTime,.05);}catch(e){}
  MV.thrS=thr>MV.thrS?Math.min(thr,MV.thrS+dt*14):thr; /* monte en 70 ms, retombe d'un coup : le lâcher doit CLAQUER */
  const ld=MV.thrS>.05?Math.min(1,charge):0;
  if(MV.vu-MV.msgT>25){MV.msgT=MV.vu;MV.envoi({c:{rpmCmd:C.idle+Math.min(1.02,rpmN)*(C.redline-C.idle)*(1+.04*nA),thr:MV.thrS,load:ld,health:MV.sante}});}
  const gv=MV.niveau*dk*(fall?.7:1);
  MV.g.gain.setTargetAtTime(gv,AC.currentTime,.05);
  MV.creuse(Math.max(0,Math.min(1,(MV.niv*gv-.008)/.06)));
};
/* le moteur se tait : `net` = la mort (explosion), sinon un fondu de 0,1 s (le nitro en l'air, la pose) */
MV.mute=function(net){
  if(!MV.on||!MV.ok||!MV.g)return;
  if(net&&!MV.mort){MV.mort=true;MV.envoi({ev:'coupe'});}
  MV.g.gain.setTargetAtTime(0,AC.currentTime,net?.03:.1);MV.creuse(0);
};
MV.coup=function(f){if(MV.on&&MV.ok)MV.envoi({ev:'coup',a:f});};
window.dbgMV=function(){return {on:MV.on,ok:MV.ok,use:MV.use,fiche:MV.nom,palier:MV.lv,sante:MV.sante,etat:MV.etat,rpm:Math.round(MV.rpm),niv:+(MV.niv||0).toFixed(4),gain:MV.g?+MV.g.gain.value.toFixed(3):null,presence:+MV.pres.toFixed(2),niveau:MV.niveau};};
/* ================= LA CONSOLE DE SON (2026-09-28, session SON) =================
   Sacha : « tout ce qui se passe à l'écran doit avoir un son propre et unique, parfaitement maîtrisé et mixé, réellement
   addictif — niveau top 1 App Store ». Audit du jour (4 auditeurs) : ~40 événements visibles SANS son, cinq sons génériques
   (boostSnd, portalSnd, fanfare, le carillon de chaîne, thud) pour des dizaines d'événements — défaite comprise —, presque
   toutes les récompenses dans le même timbre de clochette, cinq compteurs de hauteur indépendants qui faisaient zigzaguer
   « la gamme qui monte », et une pose pouvant empiler 15 à 20 notes en 200 ms.
   LA NOUVELLE CHAÎNE : les sons ne sont plus bâtis ici en oscillateurs. Ils vivent dans la BANQUE (`sons-banque.js`, rendue et
   MESURÉE par l'atelier `atelier-son/` : `node atelier-son/cuire.js`) et `sfx.js` les joue — une source et un gain par
   événement, 4 bus (ui · rec · fx · amb), une salle (réverbe), et un CHEF D'ORCHESTRE qui range les récompenses simultanées
   par priorité. Tous les sons passent par MASTER : le curseur EFFETS, le compresseur et la pause s'appliquent comme avant.
   · `sfx(id,o)` = LE point d'entrée (o : st demi-tons · vol dB · pan −1…1 · t délai s · var variante). Les autres sessions
     l'appellent sous garde `typeof sfx==='function'`. Les noms : voir `sons.html` (le banc d'écoute) ou `dbgSon()`.
   · `son(id,repli)` : joue `id`, ou appelle `repli` (l'ancien son) si la console est absente.
   · ⚠ LES ANCIENNES FONCTIONS (blip, chimeNote, rewardSfx…) RESTENT EN REPLI : si `sfx.js` manque, le jeu sonne comme avant.
   · ⚠ UNE SEULE GAMME PAR VOL (`ECH`, remis à zéro au décollage) : chaque figure, palier d'échelle ou geste en l'air prend le
     degré suivant de la pentatonique ; la POSE résout sur la tonique (le verdict). Au sol, l'aura garde sa gamme (le × d'aura).
   · ⚠ LA TONALITÉ SUIT LA MUSIQUE (`sonTonSuit`, appelé par musicTick) : NÉON en fa, VITESSE en si mineur, NOCTURNAL en sol#
     mineur, NOITE en ré# mineur (mesuré) — les sons accordés sont transposés dans la pentatonique du morceau qui joue. */
var SONV2=false,ECH=0; // `var` et non `let` (débogage 2026-09-29) : lu partout dans le fichier, AVANT sa déclaration — une lecture précoce vaut « faux » au lieu de lever une erreur de zone morte
const SON_PENTA={'jeu.sansFaute':9,'jeu.palierVitesse':7}; // le PLAFOND du degré (débogage 2026-09-29 : SANS FAUTE ×22 montait à ×10) // les appelants passent un COMPTE : on le convertit en degré
/* LE MIX S'ÉCARTE sous les grands moments (duckT : moteur, vent, flamme reculent jusqu'à −6 dB puis reviennent) — les anciennes fanfares le
   faisaient, leurs remplaçants aussi. La valeur = la profondeur du creux (voir `dk` dans la boucle). */
/* (2026-10-15, pôle SON, l'audit) LE RECUL SOUS LES SIGNAUX : mesurés dans LEUR bande contre la musique de niveau, ces signaux passaient à
   ±2 dB d'elle, ou dessous (la panne sèche de nitro est dans le grave de la basse, le portail proche 6 à 9 dB sous elle) — la musique recule
   de −3 dB pendant 0,4 s quand l'un d'eux part (musique-bus.js : `recul`). Seulement là où la musique passe par WebAudio (MUS_WA). */
/* (2026-10-15, Sacha : « faut qu'on profite de la musique ») LA RÉCOLTE ET LA SÉRIE NE FONT PLUS RECULER LA MUSIQUE : la récolte part toutes
   les 5 pièces — MESURÉ au banc, 22 fois en 40 s : la musique pompait de −3 dB toutes les 1,8 s pendant qu'on ramassait. Elles sont devenues
   des sons graves et discrets (la pièce v2) : elles n'ont plus à passer DEVANT la musique. */
const SIG_RECUL={'nitro.sec':1,'flow.perdu':1,'aura.perdue':1,'portail.proche':1,'alerte.dernier':1};
function musRecul(){try{if(musWaTient()&&MUS_WA.bus)MUS_WA.bus.recul(-3,.4);if(window.POUCE_JEU)POUCE_JEU.recul();}catch(e){}}
const SON_DUCK={'frenesie.entre':.6,'cratere':.6,'impact.immeuble':.6,'verdict.3':.5,'caisse.debloquee':.5,'orbite.entre':.5,
  'moteur.palier':.45,'argent.palier':.45,'fig.jackpot':.45,'portail':.4,'jeu.miracule':.4,'aura.x10':.4,'verdict.2':.35,'pad':.3,'turbo.ultra':.3,
  'victoire':.4,'defaite':.3,'fig.monstre':.25,'pwr.n':.25,'pwr.a':.25,'pwr.v':.25,'pwr.m':.25,'pwr.x':.25,'pwr.triple':.35,
  // (2026-10-15, Sacha : « que les figures fassent plus de bruit ») le DOUM des figures écarte le moteur et le vent un instant (pas la musique)
  'fig.explose':.12,'fig.signe':.18,'combo.sceau':.35,'pose.parfait':.15,'pose.divin':.25,
  // (2026-10-14, session SON) les grands moments qui n'écartaient pas le mix alors qu'ils sonnent aussi fort que ceux du dessus (audit oreille-neuve §6) : chaque id vérifié dans la banque et appelé
  'aura.x5':.2,'aura.x8':.3,'fig.essoreuse':.25,'pwr.double':.25,'frenesie.record':.4,'verdict.1':.15,'argent.gros':.15};
function sonPd(i){i=Math.max(0,i|0);return [0,2,4,7,9][i%5]+12*Math.floor(i/5);} // i-ème degré de la pentatonique, en demi-tons
// (2026-10-14, session SON) passé le 9e degré (+21, le plafond des bases [0,12]), une gamme du vol ne se FIGE plus sur sa note : elle redescend
// et remonte l'octave haute (degrés 8-7-6-5-6-7-8-9 : +19 +16 +14 +12 +14 +16 +19 +21) — jamais plus haut qu'avant
/* (2026-10-15, Sacha : « trop de petits sons aigus… plus de sons graves et discrets ») LA GAMME DU VOL TIENT DANS UNE OCTAVE : elle montait
   jusqu'au 9e degré (+21 demi-tons : la 8e figure d'un vol, le 10e frôlé sonnaient presque deux octaves au-dessus de leur note). Elle monte
   maintenant du degré 0 au 5e (+12, l'octave), puis va et vient en haut de l'octave (degrés 4-3-4-5 : +9 +7 +9 +12). L'ancienne : 8-7-6-5-6-7-8-9 après le 9e. */
const SON_ECH_AR=[4,3,4,5];
function sonPdAR(i){i=Math.max(0,i|0);return sonPd(i<=5?i:SON_ECH_AR[(i-6)%SON_ECH_AR.length]);}
var UI_SON={t:-1e9,pd:-1e9}; // (2026-10-16) le FILET DES BOUTONS MUETS (voir uiFiletRole) : l'heure du dernier son tenté (t) et du dernier contact (pd)
/* LE CLIC DANS LA PAUSE (2026-10-16, Sacha : « chaque bouton doit avoir un son lorsqu'on clique dessus dans l'interface, chaque curseur »).
   VU au banc : dans le panneau ⏸ (RECOMMENCER, SON, MUSIQUE, TOUS LES RÉGLAGES…) et dans les réglages ouverts depuis la pause, TOUT était
   MUET — la pause ferme la sortie (BUSOUT à 0) puis endort le contexte (togglePause), et uiClic attendait la reprise (700 ms au plus : le
   plus souvent, rien ; les crans des curseurs, eux, ne passaient jamais). Un son d'INTERFACE (`ui.*`) joué pendant la pause réveille
   maintenant le contexte le temps de sonner (`pauseSon`) : les trois autres bus de la console se ferment (rec, fx, amb — des boucles
   d'ambiance y tournent encore), la sortie s'ouvre, le son part ; 0,45 s après le dernier, tout se rendort comme la pause l'avait
   laissé. Les boucles du moteur, du vent, du nitro sont déjà à zéro (togglePause), la musique est en pause. Si la partie reprend
   entre-temps (REPRENDRE et son compte 3-2-1 passent par busPlein, compté dans `busPlein.n`), elle garde la sortie ; l'extrait du
   curseur MUSIQUE (MUSAP) garde son contexte. `?pauseson=0` : la pause d'avant (muette). */
const PSON={n:0,sav:null,bp:0},PSON_ON=!/[?&]pauseson=0\b/.test(location.search);
function pauseSonDort(){return !!(PSON_ON&&paused&&SONV2&&SND.sfx&&AC&&BUSOUT&&!document.hidden&&(AC.state!=='running'||BUSOUT.gain.value<.5));}
function pauseSonFin(n){if(n!==PSON.n)return;const C=window.CCSON;
  const rend=function(){if(n!==PSON.n||!PSON.sav)return;for(const k in PSON.sav){const g=C.bus(k);if(g)g.gain.value=PSON.sav[k];}PSON.sav=null;};
  try{if(!paused||(busPlein.n|0)!==PSON.bp||document.hidden){rend();return;} // la partie (ou son compte 3-2-1) a repris la sortie : elle est à elle
    BUSOUT.gain.setTargetAtTime(0,AC.currentTime,.012);
    setTimeout(function(){if(n!==PSON.n)return;try{if(paused&&(busPlein.n|0)===PSON.bp&&!(MUSAP.t>performance.now())&&AC.state==='running')AC.suspend();}catch(e){}rend();},90);
  }catch(e){rend();}}
function pauseSon(id,o){const C=window.CCSON,n=++PSON.n;if(UI_SON)UI_SON.t=performance.now();
  try{if(!PSON.sav){PSON.sav={};for(const k of ['rec','fx','amb']){const g=C.bus(k);if(g){PSON.sav[k]=g.gain.value;g.gain.value=0;}}PSON.bp=busPlein.n|0;}
    clearTimeout(togglePause._t); // la mise en sommeil programmée par la pause attendra la fin du clic
    const t=AC.currentTime;BUSOUT.gain.cancelScheduledValues(t);BUSOUT.gain.setValueAtTime(1,t);
    const joue=function(){try{if(paused&&SND.sfx)C.play(id,o);}catch(e){}setTimeout(function(){pauseSonFin(n);},450);};
    if(AC.state!=='running'){const p=AC.resume();if(p&&p.then)p.then(joue,function(){pauseSonFin(n);});else joue();}else joue();
  }catch(e){pauseSonFin(n);}
  return null;}
function sfx(id,o){
  if(SONV2&&id.indexOf('ui.')===0&&pauseSonDort())return pauseSon(id,o); // (2026-10-16) LE CLIC DANS LA PAUSE (voir pauseSon)
  if(!SONV2||!sfxOk()||document.hidden)return null;
  try{if(UI_SON&&id!=='ui.appui'&&!(o&&o.loop))UI_SON.t=performance.now();if(o&&o.st!=null&&SON_PENTA[id])o.st=sonPd(Math.min(SON_PENTA[id],o.st));const h=window.CCSON.play(id,o);if(h&&SON_DUCK[id])duckT=Math.max(duckT,SON_DUCK[id]);if(h&&SIG_RECUL[id])musRecul();return h;}catch(e){return null;}
}
function son(id,repli,o){if(SONV2&&window.CCSON.existe(id)){sfx(id,o);return true;}if(repli)try{repli();}catch(e){}return false;}
function echSt(){return sonPdAR(ECH++);} // (2026-10-14, session SON) aller-retour au-delà du 9e degré (sonPdAR), au lieu de Math.min(9,…) // plafond au 9e degré (+21 demi-tons) : au-delà la transposition dépasse l'octave de la base // le degré SUIVANT de la gamme du vol
