  U[u]=0;U[u+1]=v0;U[u+2]=1;U[u+3]=v0;U[u+4]=0;U[u+5]=v1;U[u+6]=1;U[u+7]=v1;
  if(TRACE.lo<0||q<TRACE.lo)TRACE.lo=q;if(q>TRACE.hi)TRACE.hi=q;
