function brasExt(K,pv,d){let m=-1e9;for(const k of K)m=Math.max(m,(k.x-pv.x)*d.x+(k.y-pv.y)*d.y+(k.z-pv.z)*d.z);return m;} // ce que la caisse avance le long de d
