  const Wc=BRB.v2,R=BRB.Rk||(BRB.Rk=brasIK(0,BRB.v2.set(0,2,0),BRB.Y,null));let essais=0;const pq=BRB.pq={}; // (banc) pourquoi chaque essai a été refusé
