function illuPx(o,cl,eteint){return '<i class="pxi pxi-'+o.ic+(cl?' '+cl:'')+'" style="'+(eteint?'color:#6c6390':(/gradient/.test(o.c)?'background:'+o.c:'color:'+o.c))+'" aria-hidden="true"></i>';}
