  GAR.sw=null;GAR.go=null;GAR.sous=null;GAR.pressT=0;GAR.impactT=0;carGroup.scale.set(1,1,1);carGroup.rotation.set(0,0,0);
  if(GAR.impactMeshes)for(const m9 of GAR.impactMeshes)m9.visible=false;
