    const sz=Q.c*Q.taille[b]*P[o+7],xs=Math.round(P[o]/Q.pas)*Q.pas,ys=Math.round(P[o+1]/Q.pas)*Q.pas;  // sur la GRILLE : des cases, pas un glissé
