  for(let s9=0;s9<=L-1;s9+=40){frameAt(s9,F);if(F.p.y>yM)yM=F.p.y;if(s9<=sF){gx+=F.p.x;gz+=F.p.z;n9++;}}
  CHUTE.G.set(gx/Math.max(1,n9),yM,gz/Math.max(1,n9));CHUTE.s=Math.min(L-1,600);
