    const cvx=(vx+w*dz)*K9.suit,cvz=(vz-w*dx)*K9.suit;                       // la carrosserie à cet endroit : glissement + rotation (ω × r) — la fumée en prend une PART
    const pu=(1.2+.35*Math.hypot(cvx,cvz))*f;                               // (1) elle l'écarte
