  if(runStats.zones!==SENS_PA.z){if(runStats.zones>SENS_PA.z&&vit)SENS_PA.tp=.5;SENS_PA.z=runStats.zones;} // (une partie neuve remet zones à 0 : on se recale sans rien jouer)
