    const SIX=bez([2*rx,t0+.0875],[2*rx-.14,t0-.1525],[0,t0+.1375],[0,cyb],NH).concat(ell(rx,cyb,rx,ry,Math.PI,-Math.PI,52).slice(1)); /* le 6 : la crosse, qui descend et s'enroule en ventre (NH : où elle finit) */
